const defaults={holdings:[],alerts:{daily:true,news:true,trend:true,time:'08:00',scope:'portfolio'},sources:[]};
let state=structuredClone(defaults),committedState=structuredClone(defaults),currentUser=null,stateRevision=0,isSaving=false;
let page='overview',newsFilter='all',selectedStock=state.holdings[0]?.symbol||'PTT',query='',toastTimer;
const $=s=>document.querySelector(s),escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(n,d=2)=>Number(n).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});
const stock=symbol=>stocks.find(s=>s.symbol===symbol);
const logo=s=>`<span class="company-logo ${s.color}">${s.logo}</span>`;
async function save(){
  if(isSaving||!currentUser)return false;
  isSaving=true;
  try{
    const result=await api('/api/state',{method:'PUT',body:{state,userId:currentUser.id,revision:stateRevision}});
    state=result.state;stateRevision=result.revision;committedState=structuredClone(state);return true;
  }catch(error){
    state=structuredClone(committedState);
    if(error.status===401)showSignedOut('login');
    if(error.status===409){
      try{const latest=await api('/api/session');if(!latest.user||latest.user.id!==currentUser?.id)showSignedOut('login');else{state=latest.state;stateRevision=latest.revision;committedState=structuredClone(state);if($('#modal').open)$('#modal').close();render();}}catch{showSignedOut('login');}
    }
    toast(error.message);return false;
  }finally{isSaving=false}
}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function totals(){return state.holdings.reduce((a,h)=>({value:a.value+stock(h.symbol).price*h.qty,cost:a.cost+h.cost*h.qty}),{value:0,cost:0})}
function header(title,sub,action=''){return `<div class="page-header"><div><div class="eyebrow">A CLEARER VIEW. EVERY DAY.</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="heading-actions">${action}</div></div>`}
function spark(down=false){return `<svg class="sparkline" viewBox="0 0 70 30" fill="none" aria-hidden="true"><path d="${down?'M1 7 10 10 15 5 22 16 30 12 39 21 47 17 56 24 68 23':'M1 25 9 21 15 24 21 12 27 18 36 15 44 19 50 9 57 12 68 3'}" stroke="${down?'#cc9990':'#8cae96'}" stroke-width="1.5"/></svg>`}
function markets(){return `<div class="market-strip">${[['SET INDEX','1,425.60','+0.82%',false],['SET50','915.24','+0.64%',false],['S&P 500','5,782.76','−0.18%',true],['USD / THB','33.42','+0.12%',false]].map(([label,value,change,down])=>`<div class="market-item"><div><div class="market-name"><i></i>${label}<span style="font-size:7px">· สาธิต</span></div><div class="market-value">${value}<span class="change ${down?'down':''}">${change}</span></div></div>${spark(down)}</div>`).join('')}</div>`}
function brief(){return `<section class="daily-brief"><div class="brief-top">${icon('spark')} YOUR DAILY BRIEF <span class="read-time">${icon('clock').replace('<svg','<svg style="display:inline;width:10px;height:10px;vertical-align:middle"')} อ่านจบใน 2 นาที</span></div><h2>เริ่มวันด้วยภาพที่ชัดขึ้น<br>ข่าวไหนสำคัญกับพอร์ตของคุณ?</h2><p>รวบรวมเรื่องราวจากบริษัท คู่ค้า และสื่อการเงิน<br>ให้คุณเห็นประเด็นสำคัญ โดยไม่ต้องเปิดอ่านหลายเว็บไซต์</p><div class="brief-bottom"><div class="source-bubbles"><b>IR</b><b>SET</b><b>FIN</b><span>บทสรุปตัวอย่าง · 3 ประเภทแหล่งข้อมูล</span></div><button class="text-button" data-action="brief">อ่านสรุปวันนี้ ${icon('arrow')}</button></div></section>`}
function newsItem(n){const s=stock(n.symbol);return `<article class="news-card">${logo(s)}<div><div class="news-meta"><span class="ticker-tag">${s.symbol}</span><span>·</span><span>${n.source}</span><span class="sentiment ${n.positive?'':'negative'}">${n.positive?'↗ ปัจจัยบวก':'↘ ปัจจัยกดดัน'}</span></div><button class="news-title" data-article="${n.id}">${n.title}</button><p class="news-desc">${n.desc}</p><div class="news-bottom">${icon('clock')} ${n.time} · เวลาสาธิต <span>·</span> ตัวอย่างการอ้างอิง ${n.sources} แหล่ง ${state.holdings.some(h=>h.symbol===s.symbol)?'<span class="related">● อยู่ในพอร์ตของคุณ</span>':''}</div></div></article>`}
function newsSection(compact=false){let list=articles.filter(n=>newsFilter==='all'||newsFilter==='portfolio'&&state.holdings.some(h=>h.symbol===n.symbol)||n.type===newsFilter);if(compact)list=list.slice(0,3);return `<section class="card"><div class="section-title"><h2>${compact?'ข่าวที่ไม่ควรพลาด':'ข่าวสาร & บทสรุป'} <span class="counter">${list.length}</span></h2>${compact?'<button class="text-button" data-page="news">ดูข่าวทั้งหมด ↗</button>':'<small>ทุกข่าวเป็นตัวอย่างเพื่อออกแบบ</small>'}</div><div class="tabs" role="group" aria-label="กรองข่าว">${[['all','ทั้งหมด'],['portfolio','หุ้นในพอร์ต'],['company','เว็บไซต์บริษัท'],['partner','คู่ค้า'],['finance','สื่อการเงิน']].map(([v,t])=>`<button class="tab ${newsFilter===v?'active':''}" data-filter="${v}" aria-pressed="${newsFilter===v}">${t}</button>`).join('')}</div><div class="news-list">${list.length?list.map(newsItem).join(''):'<div class="empty">ยังไม่มีหุ้นในพอร์ต<br><button class="btn" data-action="add">เพิ่มหุ้นที่คุณถืออยู่</button></div>'}</div></section>`}
function portfolioCard(){const t=totals(),gain=t.value-t.cost;return `<section class="card"><div class="section-title"><h2>พอร์ตของฉัน</h2><small>${state.holdings.length} หุ้นที่ติดตาม</small></div><div class="small-label">มูลค่ารวมจากราคาสาธิต</div><div class="portfolio-amount">${money(t.value)}<span class="unit">THB</span></div><div class="portfolio-gain ${gain<0?'down':''}">${gain>=0?'+':''}${money(gain)} (${t.cost?money(gain/t.cost*100):'0.00'}%) <span>เทียบต้นทุน</span></div><div class="allocation-bar">${state.holdings.map(h=>`<span style="width:${t.value?h.qty*stock(h.symbol).price/t.value*100:0}%;background:${stock(h.symbol).weight}"></span>`).join('')}</div>${state.holdings.slice(0,4).map(h=>{const s=stock(h.symbol);return `<div class="holding-row">${logo(s)}<div class="holding-title">${s.symbol}<small>${money(h.qty,0)} หุ้น</small></div><div class="holding-values">${money(h.qty*s.price)}<small class="${s.change<0?'down':''}">${s.change>=0?'+':''}${s.change.toFixed(2)}% วันนี้ (สาธิต)</small></div></div>`}).join('')||'<p class="small-note">เพิ่มหุ้นเพื่อเริ่มจัดข่าวตามพอร์ตของคุณ</p>'}<button class="btn full-button" data-action="add">${icon('plus')} เพิ่มหุ้นในพอร์ต</button></section>`}
function aiCard(){const s=stock(selectedStock),trend=s.up>s.flat&&s.up>s.down?'มีแนวโน้มปรับขึ้น':s.down>s.up&&s.down>s.flat?'มีแนวโน้มปรับลง':'ยังไม่มีทิศทางชัดเจน';return `<section class="card ai-card"><div class="section-title"><div class="ai-title">${icon('spark')} AI Insights</div><span class="ai-badge">EXPERIMENTAL</span></div><div class="ai-stock"><select aria-label="หุ้นสำหรับแนวโน้ม AI" id="ai-symbol">${stocks.map(o=>`<option ${o.symbol===s.symbol?'selected':''}>${o.symbol}</option>`).join('')}</select><span>กรอบเวลา 5 วันทำการ</span></div><div class="ai-trend">${s.down>s.up?'↘':s.flat>s.up?'→':icon('up')}${trend}</div><p>ยังไม่ได้เชื่อมต่อ Custom GPT<br>เปอร์เซ็นต์นี้ใช้สาธิตหน้าจอเท่านั้น</p><div class="probability" role="img" aria-label="สัดส่วนตัวอย่าง ขึ้น ${s.up}% ทรงตัว ${s.flat}% ลง ${s.down}%"><span style="width:${s.up}%"></span><span style="width:${s.flat}%"></span><span style="width:${s.down}%"></span></div><div class="probability-labels"><span>● ขึ้น ${s.up}%</span><span>● ทรงตัว ${s.flat}%</span><span>● ลง ${s.down}%</span></div><div class="ai-reason">${icon('layers')} ${s.reason}</div><button class="text-button" data-action="ai-detail">ดูเหตุผลและข้อจำกัด ${icon('arrow')}</button><div class="risk-inline">⚠ การคาดการณ์อาจผิดพลาด ไม่ใช่คำแนะนำการลงทุน<br>ข้อมูลสาธิต · ยังไม่ได้ประมวลผลด้วยโมเดล AI จริง</div></section>`}
function renderOverview(){return header('มองข่าวให้เห็นภาพ','ทุกเรื่องสำคัญของหุ้นที่คุณติดตาม อยู่ที่นี่',`<span class="date-pill">${icon('calendar')} 18 ต.ค. 2026 · วันตัวอย่าง</span><button class="btn primary" data-action="add">${icon('plus')} เพิ่มหุ้นที่ติดตาม</button>`)+markets()+`<div class="dashboard-columns"><div class="left-column">${brief()}${newsSection(true)}</div><div class="right-column">${portfolioCard()}${aiCard()}<p class="small-note"><b>ออกแบบให้ตรวจสอบย้อนกลับได้</b><br>ระบบจริงจะแสดงแหล่งข่าว เวลาอัปเดต และข้อมูลที่ใช้วิเคราะห์</p></div></div>`}
function renderPortfolio(){const t=totals();return header('พอร์ตของฉัน','กรอกหุ้นที่ถืออยู่ เพื่อจัดข่าวและแนวโน้มให้ตรงกับคุณ',`<button class="btn primary" data-action="add">${icon('plus')} เพิ่มหุ้น</button>`)+`<div class="summary-grid"><div class="card"><span class="small-label">มูลค่ารวม · ราคาสาธิต</span><div class="summary-value">฿${money(t.value)}</div></div><div class="card"><span class="small-label">ต้นทุนรวม</span><div class="summary-value">฿${money(t.cost)}</div></div><div class="card"><span class="small-label">กำไร / ขาดทุนจำลอง</span><div class="summary-value ${t.value<t.cost?'down':''}" style="${t.value>=t.cost?'color:var(--green)':''}">${t.value>=t.cost?'+':''}${money(t.value-t.cost)}</div></div></div><section class="card"><div class="table-wrap"><table><thead><tr><th>หุ้น / บริษัท</th><th>จำนวนหุ้น</th><th>ต้นทุนต่อหุ้น</th><th>ราคาสาธิต</th><th>มูลค่าสาธิต</th><th>จัดการ</th></tr></thead><tbody>${state.holdings.map(h=>`<tr><td><b>${h.symbol}</b><small>${stock(h.symbol).name}</small></td><td>${money(h.qty,0)}</td><td>${money(h.cost)}</td><td>${money(stock(h.symbol).price)}</td><td>${money(h.qty*stock(h.symbol).price)}</td><td><button class="text-button" data-edit="${h.symbol}">แก้ไข</button><button class="remove" data-remove="${h.symbol}">นำออก</button></td></tr>`).join('')}</tbody></table>${!state.holdings.length?'<div class="empty">ยังไม่มีหุ้นในพอร์ต เริ่มเพิ่มหุ้นที่คุณสนใจได้เลย</div>':''}</div><p class="small-note" style="margin-top:18px">ข้อมูลพอร์ตบันทึกแยกตามบัญชีบนเซิร์ฟเวอร์ · ราคาตลาดยังเป็นข้อมูลสาธิต</p></section>`}
function companyCards(){const q=query.trim().toLowerCase(),list=stocks.filter(s=>`${s.symbol} ${s.name} ${s.sector}`.toLowerCase().includes(q));return list.map(s=>`<article class="card company-card">${logo(s)}<h3>${s.symbol} <span class="unit">SET</span></h3><p>${s.name}<br>${s.sector}</p><button class="btn" data-company="${s.symbol}">ดูข้อมูลบริษัท ${icon('arrow')}</button></article>`).join('')||'<div class="empty">ไม่พบบริษัทในชุดข้อมูลตัวอย่าง<br>ลองค้นหา PTT, ADVANC, CPALL, KBANK, AOT หรือ SCB</div>'}
function renderSearch(){return header('ค้นหาบริษัท','เริ่มจากชื่อหุ้น ชื่อบริษัท หรือกลุ่มอุตสาหกรรม')+`<label class="large-search">${icon('search')}<input type="search" id="company-query" placeholder="ค้นหา เช่น PTT, กสิกรไทย, พลังงาน..." value="${escapeHtml(query)}" aria-label="ค้นหาบริษัท"></label><p class="small-note" style="margin-bottom:16px">บริษัทตัวอย่าง 6 แห่ง · การเชื่อมข้อมูลตลาดจริงจะเพิ่มในขั้นพัฒนา</p><div class="company-grid" id="company-results">${companyCards()}</div>`}
function renderAlerts(){const a=state.alerts;return header('การแจ้งเตือน','กำหนดข่าวและแนวโน้มที่คุณอยากติดตาม')+`<div class="settings"><div class="info-box">หน้าตัวอย่างการตั้งค่า · บันทึกความต้องการในบัญชีได้ แต่ยังไม่ส่ง Push, อีเมล หรือรันงานอัตโนมัติขณะปิดแอป</div><form id="alert-form" class="card">${[['daily','สรุปข่าวประจำวัน','รวมข่าวที่เกี่ยวข้องกับหุ้นที่เลือกเป็นบทสรุปเดียว'],['news','ข่าวสำคัญของบริษัท','แจ้งเมื่อมีประกาศบริษัท งบการเงิน หรือความร่วมมือใหม่'],['trend','เมื่อแนวโน้ม AI เปลี่ยน','แจ้งการเปลี่ยนทิศทาง พร้อมเหตุผลและคำเตือนทุกครั้ง']].map(([key,title,desc])=>`<label class="setting-row"><span><h3>${title}</h3><p>${desc}</p></span><input class="switch" type="checkbox" name="${key}" ${a[key]?'checked':''}></label>`).join('')}<label class="setting-row"><span><h3>เวลาสรุปข่าวรายวัน</h3><p>เวลาไทย · Asia/Bangkok</p></span><input type="time" name="time" required value="${/^\d{2}:\d{2}$/.test(a.time)?a.time:'08:00'}"></label><label class="setting-row"><span><h3>หุ้นที่ต้องการติดตาม</h3><p>ใช้รายการจากพอร์ต หรือทุกบริษัทในชุดสาธิต</p></span><select name="scope"><option value="portfolio" ${a.scope==='portfolio'?'selected':''}>หุ้นในพอร์ตของฉัน</option><option value="all" ${a.scope==='all'?'selected':''}>ทุกบริษัทในชุดสาธิต</option></select></label><button class="btn primary" style="margin-top:20px" type="submit">บันทึกการตั้งค่า</button></form><section class="card" style="margin-top:20px"><div class="section-title"><h2>ตัวอย่างการแจ้งเตือน</h2><span class="demo-label">PREVIEW</span></div><h3 style="font-size:13px">${stock(selectedStock).symbol} · แนวโน้ม AI มีการเปลี่ยนแปลง</h3><p class="small-note" style="margin:10px 0">เปิดดูเหตุผล แหล่งข้อมูล และกรอบเวลาที่ใช้วิเคราะห์<br>⚠ AI อาจผิดพลาด ไม่ใช่คำแนะนำการลงทุน · ข้อมูลสาธิต</p><button class="text-button" data-page="insights">ดูแนวโน้ม ${icon('arrow')}</button></section></div>`}
function renderSources(){return renderSourceManager()}
function render(){if(!currentUser)return;const names={overview:'ภาพรวม',news:'ข่าวสาร & บทสรุป',portfolio:'พอร์ตของฉัน',insights:'AI Insights',search:'ค้นหาบริษัท',alerts:'การแจ้งเตือน',sources:'แหล่งข้อมูล'};$('#breadcrumb').textContent=names[page];document.querySelectorAll('.nav').forEach(n=>{n.classList.toggle('active',n.dataset.page===page);if(n.dataset.page===page)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current')});const views={overview:renderOverview,news:()=>header('ข่าวสาร & บทสรุป','อ่านประเด็นสำคัญ เชื่อมโยงบริษัท และตรวจสอบที่มา')+newsSection(),portfolio:renderPortfolio,search:renderSearch,alerts:renderAlerts,sources:renderSources,insights:()=>header('AI Insights','มองแนวโน้มพร้อมเหตุผล เพื่อประกอบการศึกษาข้อมูล')+`<div class="wide-ai"><section class="card agent-notice">${icon('spark')}<div><h3>Custom GPT ของคุณ · ยังไม่ได้เชื่อมต่อ</h3><p>การนำคำสั่งและความรู้ของ GPT มาใช้วิเคราะห์ในแอปต้องเชื่อม AI ฝั่งเซิร์ฟเวอร์ก่อน ผลด้านล่างยังเป็นตัวอย่างหน้าจอ</p></div></section><div class="info-box">เปอร์เซ็นต์และแนวโน้มทั้งหมดเป็นค่าจำลองเพื่อออกแบบ UI ไม่ใช่ผลพยากรณ์จริงหรือความแม่นยำที่ผ่านการทดสอบ</div>${aiCard()}<section class="card" style="margin-top:20px"><h2>เบื้องหลังการประเมิน</h2><div class="detail-block"><h3>01 · ข่าวและข้อเท็จจริง</h3><p>แยกข้อมูลจากบริษัท คู่ค้า และสื่อ พร้อมระบุแหล่งอ้างอิง</p></div><div class="detail-block"><h3>02 · สัญญาณและความเสี่ยง</h3><p>แสดงทั้งปัจจัยสนับสนุน ปัจจัยกดดัน และข้อมูลที่ยังขาด</p></div><div class="detail-block"><h3>03 · ยอมรับความไม่แน่นอน</h3><p>ระบบจริงต้องทดสอบย้อนหลังและตรวจสอบความน่าเชื่อถือของความน่าจะเป็น หากข้อมูลไม่เพียงพอให้แสดง “ยังประเมินไม่ได้”</p></div></section></div>`};$('#main').innerHTML=views[page]();}
function navigate(next){if(!currentUser)return;page=next;history.replaceState(null,'','#'+next);render();window.scrollTo({top:0,behavior:'instant'})}
function openModal(title,body){$('#modal-title').textContent=title;$('#modal-body').innerHTML=body;$('#modal').showModal()}
function addHolding(symbol,edit=false){const h=edit?state.holdings.find(v=>v.symbol===symbol):null;openModal(edit?'แก้ไขหุ้นในพอร์ต':'เพิ่มหุ้นที่คุณถืออยู่',`<p class="form-help">กรอกจำนวนและต้นทุน เพื่อจัดข่าวและคำนวณมูลค่าจากราคาสาธิต</p><form id="holding-form" data-edit="${edit?'yes':'no'}"><label class="field">บริษัท / ชื่อหุ้น<select name="symbol" ${edit?'disabled':''}>${stocks.map(s=>`<option value="${s.symbol}" ${s.symbol===(symbol||'PTT')?'selected':''}>${s.symbol} — ${s.name}</option>`).join('')}</select></label><label class="field">จำนวนหุ้น<input type="number" name="qty" min="1" max="1000000000" step="1" required placeholder="เช่น 1,000" value="${h?h.qty:''}"></label><label class="field">ต้นทุนเฉลี่ยต่อหุ้น (บาท)<input type="number" name="cost" min="0" max="10000000" step="0.01" required placeholder="เช่น 32.50" value="${h?h.cost:''}"></label><p class="form-help">${edit?'บันทึกเพื่อแทนที่จำนวนและต้นทุนเดิม':'หากมีหุ้นนี้แล้ว จะรวมจำนวนและคำนวณต้นทุนเฉลี่ยใหม่'}<br>ข้อมูลบันทึกในบัญชีที่คุณเข้าสู่ระบบ</p><button class="btn primary" type="submit">${edit?'บันทึกการแก้ไข':'เพิ่มหุ้นในพอร์ต'}</button></form>`)}
document.addEventListener('click',async e=>{if(!currentUser)return;if(isSaving){toast('กำลังบันทึก กรุณารอสักครู่');return;}const el=e.target.closest('button,a');if(!el)return;if(el.dataset.page){navigate(el.dataset.page);return}if(el.classList.contains('brand')){navigate('overview');return}if(el.id==='quick-search'){navigate('search');$('#company-query').focus()}if(el.id==='close-modal')$('#modal').close();if(el.dataset.filter){newsFilter=el.dataset.filter;render()}if(el.dataset.action==='add')addHolding();if(el.dataset.edit)addHolding(el.dataset.edit,true);if(el.dataset.remove){const s=el.dataset.remove;openModal('นำหุ้นออกจากพอร์ต',`<p>นำ ${s} ออกจากพอร์ตสาธิตและตัวกรองข่าวหุ้นในพอร์ต?</p><button class="btn primary" data-confirm-remove="${s}">ยืนยันนำออก</button>`)}if(el.dataset.confirmRemove){state.holdings=state.holdings.filter(h=>h.symbol!==el.dataset.confirmRemove);const ok=await save();$('#modal').close();render();if(ok)toast('นำหุ้นออกจากพอร์ตแล้ว')}if(el.dataset.article){const n=articles.find(a=>a.id===Number(el.dataset.article));openModal(n.title,`<div class="info-box">ข่าวสาธิต · ไม่ใช่ข่าวจริงของ ${n.symbol}</div><p>${n.details}</p><div class="detail-block"><h3>สิ่งที่แสดงในระบบจริง</h3><p>สรุปข้อเท็จจริง • ผลกระทบที่อาจเกิดขึ้น • สิ่งที่ยังไม่ทราบ • ลิงก์แหล่งข้อมูลพร้อมเวลาเผยแพร่</p></div><p class="form-help" style="margin-top:15px">ยังไม่มีลิงก์ต้นฉบับ เพราะเนื้อหานี้สร้างขึ้นเพื่อสาธิตการออกแบบเท่านั้น</p>`)}if(el.dataset.action==='brief'){const list=articles.filter(n=>state.holdings.some(h=>h.symbol===n.symbol));openModal('บทสรุปประจำวันของคุณ',`<div class="info-box">ตัวอย่างบทสรุปจากหุ้นในพอร์ต · ยังไม่มีการดึงข่าวสด</div>${list.map(n=>`<div class="detail-block"><h3>${n.symbol} · ${n.positive?'ประเด็นสนับสนุน':'ประเด็นที่ต้องจับตา'}</h3><p>${n.title}</p></div>`).join('')||'<p>เพิ่มหุ้นในพอร์ตเพื่อเลือกหัวข้อที่เกี่ยวข้อง</p>'}`)}if(el.dataset.action==='ai-detail'){const s=stock(selectedStock);openModal(`เหตุผลและข้อจำกัด · ${s.symbol}`,`<div class="info-box">ข้อมูลสาธิต — ไม่ได้ใช้โมเดลทำนายจริง</div><div class="detail-block"><h3>ตัวอย่างปัจจัยที่ใช้ประกอบ</h3><p>${s.reason}</p></div><div class="detail-block"><h3>ความเสี่ยงที่ต้องพิจารณา</h3><p>ข้อมูลข่าวอาจล่าช้า ไม่ครบ หรือถูกสะท้อนในราคาไปแล้ว เหตุการณ์ใหม่อาจทำให้ทิศทางเปลี่ยนทันที</p></div><div class="detail-block"><h3>ความหมายของเปอร์เซ็นต์</h3><p>ตัวเลขในต้นแบบเป็นค่าที่กำหนดไว้เพื่อทดสอบหน้าจอ ไม่ใช่ความแม่นยำหรือความน่าจะเป็นที่ผ่านการตรวจสอบ</p></div><p class="form-help" style="margin-top:15px">กรอบเวลาตัวอย่าง 5 วันทำการ · ระบบจริงต้องระบุเวลาอัปเดต รุ่นโมเดล และผลทดสอบย้อนหลัง</p>`)}if(el.dataset.company){const s=stock(el.dataset.company);openModal(s.symbol+' · ข้อมูลบริษัท',`<p>${s.name}</p><p class="form-help">${s.sector} · ตลาด SET</p><div class="detail-block"><span class="small-label">ราคาตัวอย่าง</span><div class="portfolio-amount">฿${money(s.price)}</div></div><div class="detail-block"><h3>ข่าวที่เกี่ยวข้อง · สาธิต</h3><p>${articles.find(n=>n.symbol===s.symbol).title}</p></div><button class="btn primary" data-add-symbol="${s.symbol}">เพิ่มหุ้นนี้ในพอร์ต</button><button class="btn full-button" data-ai-symbol="${s.symbol}">ดูแนวโน้ม AI ตัวอย่าง</button>`)}if(el.dataset.addSymbol){$('#modal').close();addHolding(el.dataset.addSymbol)}if(el.dataset.aiSymbol){selectedStock=el.dataset.aiSymbol;$('#modal').close();navigate('insights')}});
document.addEventListener('input',e=>{if(e.target.id==='company-query'){query=e.target.value;$('#company-results').innerHTML=companyCards()}});
document.addEventListener('change',e=>{if(e.target.id==='ai-symbol'){selectedStock=e.target.value;render()}});
document.addEventListener('submit',async e=>{if(!currentUser)return;if(isSaving){e.preventDefault();return;}if(e.target.id==='holding-form'){e.preventDefault();const f=e.target,symbol=f.elements.symbol.value,qty=Number(f.elements.qty.value),cost=Number(f.elements.cost.value);if(!stock(symbol)||!Number.isInteger(qty)||qty<=0||qty>1e9||!Number.isFinite(cost)||cost<0||cost>1e7)return;const existing=state.holdings.find(h=>h.symbol===symbol);if(existing){if(f.dataset.edit==='yes'){existing.qty=qty;existing.cost=cost}else{const total=existing.qty+qty;if(total>1e9){toast('จำนวนหุ้นรวมเกินขอบเขตชุดสาธิต');return}existing.cost=(existing.cost*existing.qty+cost*qty)/total;existing.qty=total}}else state.holdings.push({symbol,qty,cost});const ok=await save();$('#modal').close();render();if(ok)toast(`บันทึก ${symbol} ในพอร์ตแล้ว`)}if(e.target.id==='alert-form'){e.preventDefault();const f=e.target;state.alerts={daily:f.elements.daily.checked,news:f.elements.news.checked,trend:f.elements.trend.checked,time:f.elements.time.value,scope:f.elements.scope.value};if(await save())toast('บันทึกการตั้งค่าตัวอย่างแล้ว · ยังไม่มีการส่งแจ้งเตือนจริง')}});
document.addEventListener('keydown',e=>{if(currentUser&&e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#modal').open){e.preventDefault();navigate('search');$('#company-query').focus()}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
